(38215, 'Numbers 1:18', 'Numbers', 1, 18, 'د دوهمې میاشتې په لومړۍ ورځ ټول قوم راوغوښت. خلکو خپل نومونه طایفه په طایفه او کورنۍ په کورنۍ ولیکل او هغه کسان چې عمر یې شل کاله یا زیات ؤ د هر یو نوم په لست کې ولیکل شو.', 'د دوهمې میاشتې په لومری ورج تول قوم راوغوشت. خلکو خپل نومونه طایفه په طایفه او کورنی په کورنی ولیکل او هغه کسان چې عمر یې شل کاله یا زیات و د هر یو نوم په لست کې ولیکل شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_1_18.mp3', 'https://drive.google.com/file/d/1h8qb44ft08oLyAbv4GHn1ofw6xqm9txo/preview', 1761237839, 1761237839),
(38216, 'Numbers 1:19', 'Numbers', 1, 19, 'څنګه چې څښتن موسی ته امر کړی ؤ، هغوی یې د سینا په دښته کې وشمېرل.', 'چنګه چې چشتن موسی ته امر کری و، هغوی یې د سینا په دشته کې وشمېرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_1_19.mp3', 'https://drive.google.com/file/d/1WJ9Q4_ErBpf-grGQ23nO5iDS_r5zjW_p/preview', 1761237839, 1761237839),
(38217, 'Numbers 1:47', 'Numbers', 1, 47, 'خو هغه خلک چې د لاوي د قبیلې څخه وو په دې کې شامل نه وو،', 'خو هغه خلک چې د لاوی د قبیلې چخه وو په دې کې شامل نه وو،', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38218, 'Numbers 1:48', 'Numbers', 1, 48, 'ځکه چې څښتن موسی ته ویلي وو:', 'جکه چې چشتن موسی ته ویلی وو:', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38219, 'Numbers 1:49', 'Numbers', 1, 49, '«کله چې ته د هغو کسانو سرشمېرنه کوې چې جنګ کولای شي، نو د لاوي قبیله په کې مه شاملوه.', '«کله چې ته د هغو کسانو سرشمېرنه کوې چې جنګ کولای شی، نو د لاوی قبیله په کې مه شاملوه.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38220, 'Numbers 1:50', 'Numbers', 1, 50, 'د هغې په ځای لاویان د سپېڅلې خېمې او د هغې د ټول سامان مسوولان وټاکه. هغوی به دا خېمه او د هغې سامان وړي، ساتنه به یې کوي او د هغې په شاوخوا کې به خپلې خېمې ودروي.', 'د هغې په جای لاویان د سپېچلې خېمې او د هغې د تول سامان مسوولان وتاکه. هغوی به دا خېمه او د هغې سامان وری، ساتنه به یې کوی او د هغې په شاوخوا کې به خپلې خېمې ودروی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38221, 'Numbers 1:51', 'Numbers', 1, 51, 'هرکله چې تاسو خپلې خېمې بل ځای ته وړئ، نو لاویان دې سپېڅلې خېمه راټوله کړي او په نوي ځای کې دې بیا ودروي. که بل هرڅوک ورته نژدې ورشي وبه وژل شي.', 'هرکله چې تاسو خپلې خېمې بل جای ته وری، نو لاویان دې سپېچلې خېمه راتوله کری او په نوی جای کې دې بیا ودروی. که بل هرچوک ورته نژدې ورشی وبه وژل شی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38222, 'Numbers 1:52', 'Numbers', 1, 52, 'پاتې اسراییلیان به د خپلو ډلو له مخې خېمې ودروي، هر سړی به د خپل بیرغ لاندې د خپلې ډلې سره وي.', 'پاتې اسراییلیان به د خپلو دلو له مخې خېمې ودروی، هر سری به د خپل بیرغ لاندې د خپلې دلې سره وی.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38223, 'Numbers 1:53', 'Numbers', 1, 53, 'خو لاویان به خپلې خېمې د سپېڅلې خېمې په شاوخوا کې ودروي، ترڅو د اسراییلو په قوم باندې زما قهر نازل نه شي. لاویان دې د سپېڅلې خېمې د ساتلو مسوولیت په غاړه واخلي.»', 'خو لاویان به خپلې خېمې د سپېچلې خېمې په شاوخوا کې ودروی، ترچو د اسراییلو په قوم باندې زما قهر نازل نه شی. لاویان دې د سپېچلې خېمې د ساتلو مسوولیت په غاره واخلی.»', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38224, 'Numbers 1:54', 'Numbers', 1, 54, 'څنګه چې څښتن موسی ته امر کړی ؤ، اسراییلیانو کټ مټ هماغسې وکړل.', 'چنګه چې چشتن موسی ته امر کری و، اسراییلیانو کت مت هماغسې وکرل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(38225, 'Genesis 8:1', 'Genesis', 8, 1, 'خدای نوح او هغه ټول حیوانات چې په کشتۍ کې د هغه سره وو را په یاد کړل، نو خدای په ځمکه باندې باد راوالوزاوه او اوبه په کمېدلو شوې.', 'خدای نوح او هغه تول حیوانات چې په کشتی کې د هغه سره وو را په یاد کرل، نو خدای په جمکه باندې باد راوالوزاوه او اوبه په کمېدلو شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38226, 'Genesis 8:2', 'Genesis', 8, 2, 'خدای د ځمکې لاندې اوبه او د اسمان د اوبو دروازې بندې کړې او باران ودرېده.', 'خدای د جمکې لاندې اوبه او د اسمان د اوبو دروازې بندې کرې او باران ودرېده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38227, 'Genesis 8:3', 'Genesis', 8, 3, 'په یوسلو پنځوسو ورځو کې اوبه ورو، ورو د ځمکې د مخ څخه کمې شوې.', 'په یوسلو پنجوسو ورجو کې اوبه ورو، ورو د جمکې د مخ چخه کمې شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38228, 'Genesis 8:4', 'Genesis', 8, 4, 'او د اوومې میاشتې په اوولسمه ورځ کشتۍ د ارارات په غرونو باندې ودرېدله.', 'او د اوومې میاشتې په اوولسمه ورج کشتی د ارارات په غرونو باندې ودرېدله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38229, 'Genesis 8:5', 'Genesis', 8, 5, 'اوبه کمې شوې او د لسمې میاشتې په لومړۍ ورځ د غرونو څوکې ښکاره شوې.', 'اوبه کمې شوې او د لسمې میاشتې په لومری ورج د غرونو چوکې شکاره شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38230, 'Genesis 8:6', 'Genesis', 8, 6, 'وروسته له څلوېښتو ورځو نوح د کشتۍ کړکۍ خلاصه کړه', 'وروسته له چلوېشتو ورجو نوح د کشتی کرکی خلاصه کره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38231, 'Genesis 8:7', 'Genesis', 8, 7, 'او یو کارغه یې دباندې ولېږه، خو کارغه به یو خوا او بل خواته الوت، تر هغې پورې چې ځمکه وچه شوه.', 'او یو کارغه یې دباندې ولېزه، خو کارغه به یو خوا او بل خواته الوت، تر هغې پورې چې جمکه وچه شوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38232, 'Genesis 8:8', 'Genesis', 8, 8, 'نوح غوښتل پوه شي چې ایا د ځمکې په مخ باندې اوبه کمې شوې دي یا نه، نو یوه کوتره یې والوزوله.', 'نوح غوشتل پوه شی چې ایا د جمکې په مخ باندې اوبه کمې شوې دی یا نه، نو یوه کوتره یې والوزوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38233, 'Genesis 8:9', 'Genesis', 8, 9, 'خو کوترې د خپل ځان دپاره د ناستې ځای پیدا نه کړ ځکه چې د ځمکې په مخ باندې لا اوبه ولاړې وې او هغه بېرته کشتۍ ته راستنه شوه. نوح خپل لاس وراوږد کړ، هغه یې ونیوله او کشتۍ ته یې ننه‌ایستله.', 'خو کوترې د خپل جان دپاره د ناستې جای پیدا نه کر جکه چې د جمکې په مخ باندې لا اوبه ولارې وې او هغه بېرته کشتی ته راستنه شوه. نوح خپل لاس وراوزد کر، هغه یې ونیوله او کشتی ته یې ننه‌ایستله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38234, 'Genesis 8:10', 'Genesis', 8, 10, 'هغه اووه ورځې نور صبر وکړ او بیا یې کوتره ولېږله.', 'هغه اووه ورجې نور صبر وکر او بیا یې کوتره ولېزله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38235, 'Genesis 8:11', 'Genesis', 8, 11, 'کوتره د ماښام په وخت کې بېرته هغه ته راستنه شوه او د زیتون تازه پاڼه یې په مښوکه کې نیولې وه، نو نوح پوه شو چې اوبه کمې شوې دي.', 'کوتره د ماشام په وخت کې بېرته هغه ته راستنه شوه او د زیتون تازه پانه یې په مشوکه کې نیولې وه، نو نوح پوه شو چې اوبه کمې شوې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(38236, 'Genesis 8:12', 'Genesis', 8, 12, 'هغه اووه ورځې نور انتظار وکړ او یوځل بیا یې کوتره ولېږله، خو دا ځل هغه بېرته رانغله.', 'هغه اووه ورجې نور انتظار وکر او یوجل بیا یې کوتره ولېزله، خو دا جل هغه بېرته رانغله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(38237, 'Genesis 8:13', 'Genesis', 8, 13, 'په هغه وخت کې نوح د شپږ سوه یو کالو په عمر ؤ. د هماغه کال د اولې میاشتې په لومړۍ نېټه ځمکه مخ په وچېدلو شوه. نوح د کشتۍ پوښ لېرې کړ، شاوخوا یې وکتل او ویې لیدل چې د ځمکې مخ وچ شوی ؤ.', 'په هغه وخت کې نوح د شپز سوه یو کالو په عمر و. د هماغه کال د اولې میاشتې په لومری نېته جمکه مخ په وچېدلو شوه. نوح د کشتی پوش لېرې کر، شاوخوا یې وکتل او ویې لیدل چې د جمکې مخ وچ شوی و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_8_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
